% ========================================
% Step 1 — tokens: text chopped into LEGO bricks.
% Presenter: the model never sees letters, only tokens. Emoji and names get
% chopped too --- that's why AI is sometimes clumsy with unusual spellings.
% ========================================
\section{Step 1: Chop it up}

\begin{frame}{Tokens --- the LEGO bricks of text\hfill\includegraphics[height=0.45cm]{images/icons/interface-searching.pdf}}
    \begin{itemize}
        \item First, the sentence is chopped into chunks called \textbf{tokens}
    \end{itemize}
    \begin{center}
    \begin{tikzpicture}[font=\small]
        \only<1>{\node[font=\Large] at (4.0,0.4) {The robot read a book};}
        % box centres spaced so the visual gap between bricks stays even
        \visible<2->{\node[draw, rounded corners, fill=msblue!20,  minimum width=1.5cm, minimum height=0.85cm] (a) at (0,0)    {The};}
        \visible<3->{\node[draw, rounded corners, fill=msgreen!20, minimum width=1.9cm, minimum height=0.85cm] (b) at (2.0,0)  {robot};}
        \visible<4->{\node[draw, rounded corners, fill=msorange!20,minimum width=1.8cm, minimum height=0.85cm] (c) at (4.15,0) {read};}
        \visible<5->{\node[draw, rounded corners, fill=msyellow!25,minimum width=1.2cm, minimum height=0.85cm] (d) at (5.95,0) {a};}
        \visible<6->{\node[draw, rounded corners, fill=msturquoise!20,minimum width=1.8cm, minimum height=0.85cm] (e) at (7.75,0) {book};}
        \visible<7->{\node[font=\small, text=msblue] at (3.9,-1.3) {the model never sees letters --- only bricks like these};}
    \end{tikzpicture}
    \end{center}
    \visible<8->{\begin{itemize}
        \item Common words are one brick; longer or rarer words get split into pieces
        \item Chunks are easier to count, stack and reuse --- just like LEGO
    \end{itemize}}
    % PRESENTER: reveal one brick per click. Ask: why not one brick per
    % LETTER? (too many steps, no meaning). Why not whole sentences?
    % (too few examples to learn from).
\end{frame}
=== embeddings
% ========================================
% Step 2 — embeddings: every token becomes a point in a map of meaning.
% Neighbourhoods are TINTED HALOS (no stroked outlines — a dashed line
% always ends up slicing through a label). Presenter: the real map has
% thousands of directions; we draw two. SIMILAR = CLOSE is the point.
% ========================================
\section{Step 2: Give every brick a home}

\begin{frame}{A map of meaning\hfill\includegraphics[height=0.45cm]{images/icons/leisure-island-and-palm-trees.pdf}}
    \begin{itemize}
        \item Each token becomes a list of numbers --- a \textbf{point on a giant map of meaning}
    \end{itemize}
    \begin{center}
    \begin{tikzpicture}[font=\small]
        % axes (revealed first)
        \draw[->, msblack!40] (-3.4,0) -- (3.4,0) node[below right, text=msblack!40, font=\scriptsize] {more \emph{thing-like}};
        \draw[->, msblack!40] (0,-2.4) -- (0,2.8) node[above left, text=msblack!40, font=\scriptsize] {more \emph{alive}};
        % meaning neighbourhoods: soft tints UNDER the words (drawn first
        % in code so the tint never washes over a label)
        \visible<5->{\fill[msgreen!15] (1.7,0.9) ellipse (1.55cm and 0.75cm);}
        \visible<5->{\node[text=msgreen!70!black, font=\scriptsize] at (2.85,0.25) {pets};}
        \visible<6->{\fill[mspurple!15] (-1.55,1.75) ellipse (1.45cm and 0.85cm);}
        \visible<6->{\node[text=mspurple, font=\scriptsize] at (-1.5,0.68) {royalty};}
        % words as points; labels placed away from lines and edges
        \visible<2->{\fill[msblue] (1.1,0.6) circle (2.5pt) node[below=3pt] {cat};}
        \visible<3->{\fill[msblue] (1.9,1.1) circle (2.5pt) node[right=2pt] {dog};}
        \visible<4->{\fill[mspurple] (-2.0,1.6) circle (2.5pt) node[left=2pt] {king};}
        \visible<4->{\fill[mspurple] (-1.05,2.2) circle (2.5pt) node[above=2pt] {queen};}
        \visible<4->{\fill[msorange] (1.5,-1.6) circle (2.5pt) node[below right] {banana};}
        \visible<7->{\node[text=msblue, font=\small] at (0,-3.0) {close on the map = similar in meaning};}
    \end{tikzpicture}
    \end{center}
    % PRESENTER: the real map has thousands of directions --- we're showing
    % 2 so brains don't melt. Punchline: "king - man + woman" lands near
    % "queen"; the map learned that from reading, nobody typed it in.
\end{frame}
=== attention
% ========================================
% Step 3 — attention: every word looks at every other word and decides
% who matters. Reveal the guessing question first, then the lines,
% thickest last. THE star diagram of the deck — take your time here.
% ========================================
\section{Step 3: Who matters?}

\begin{frame}{Attention --- every word looks at every other word\hfill\includegraphics[height=0.45cm]{images/icons/interface-searching.pdf}}
    \begin{itemize}
        \item To understand \textbf{it}, the model lets every word look at every other word --- and decide who matters
    \end{itemize}
    \begin{center}
    \begin{tikzpicture}[font=\scriptsize]
        \foreach \w [count=\i from 0] in {The, dragon, guarded, the, gold, because, it, was, shiny} {
            \node[draw, rounded corners, fill=msblue!12, minimum width=1.15cm, minimum height=0.7cm]
                (t\i) at (1.35*\i,0) {\w};
        }
        \visible<2->{\node[draw, rounded corners, fill=msred!30, minimum width=1.15cm, minimum height=0.7cm] at (1.35*6,0) {it};}
        % attention lines from "it" (t6): thickness = how much it matters.
        % Leftward targets bend right (arc above), rightward bend left —
        % keeps every arc over the top of the row, never inside the boxes.
        \visible<3->{\draw[->, msorange, line width=2.4pt] (t6.north) to[bend right=30] (t4.north);}   % gold: the answer
        \visible<3->{\draw[->, msorange, line width=1.4pt] (t6.north) to[bend left=40] (t8.north);}    % shiny: the clue
        \visible<4->{\draw[->, msblack!35, line width=0.4pt] (t6.north) to[bend right=20] (t5.north);} % because
        \visible<4->{\draw[->, msblack!35, line width=0.4pt] (t6.north) to[bend left=30] (t7.north);}  % was
        \visible<5->{\draw[->, msblack!35, line width=0.4pt] (t6.north) to[bend right=45] (t1.north);} % dragon
        \visible<6->{\node[text=msblue, font=\small] at (5.4,-1.5) {thick line = matters a lot: \textbf{it} = the \emph{gold}};}
    \end{tikzpicture}
    \end{center}
    \visible<7->{\begin{itemize}
        \item This happens \emph{inside} the model, for every single word, on every single guess
    \end{itemize}}
    % PRESENTER: read the sentence aloud, ask "what does IT mean?" BEFORE
    % revealing the lines — they'll all say gold instantly, then show them
    % the model had to WORK that out. Swap in "it was guarding" to flip the
    % answer to dragon — same trick, reversed arrow.
\end{frame}
=== cache
% ========================================
% The note stack — the key-value cache, told as sticky notes.
% Show: word-5 state (bricks + their K/V notes in a tray) -> new word
% reads the STACK (one arrow, then a fan inside) -> it writes its own
% note: cache grows by exactly one entry.
% Presenter: we never re-listen to old words, we keep notes; tall stack
% = slow and heavy = why long chats degrade.
% ========================================
\section{The Note Stack}

\begin{frame}{Word 6 arrives --- and the notes are already written\hfill\includegraphics[height=0.45cm]{images/icons/technology-mars-rover.pdf}}
    \begin{center}
    \begin{tikzpicture}[font=\scriptsize]
        % word-5 state: five bricks, each with a sticky note in the tray
        \foreach \w [count=\i from 0] in {The, dragon, kept, the, gold} {
            \visible<1->{\node[draw, rounded corners, fill=msblue!12, minimum width=1.2cm, minimum height=0.65cm] (b\i) at (1.5*\i,0) {\w};}
            \visible<1->{\node[draw, fill=msyellow!45, minimum width=0.95cm, minimum height=0.5cm] (n\i) at (1.5*\i,-1.15) {K\,V};}
        }
        % the tray: one container = the cache
        \visible<1->{\node[draw=msblack!40, dashed, rounded corners, minimum width=9.6cm, minimum height=1.15cm] (tray) at (3.7,-1.15) {};}
        \visible<1->{\node[font=\scriptsize, text=msblack!60, anchor=west] at (-1.1,-1.95) {the cache --- the note stack};}
        % word 6 shows up
        \visible<2->{\node[draw, rounded corners, fill=msred!25, minimum width=1.2cm, minimum height=0.65cm] (bnew) at (7.5,0) {it};}
        % one arrow down into the tray; the whole stack lights up as it reads
        \visible<3->{\draw[->, thick, msorange] (bnew.south) -- (7.5,-0.62);}
        \visible<3->{\foreach \i in {0,...,4}
            \node[draw=msorange, very thick, rounded corners=2pt, minimum width=1.07cm, minimum height=0.58cm] at (1.5*\i,-1.15) {};}
        \visible<3->{\node[font=\small, text=msblue] at (2.6,0.95) {it reads the whole stack --- the old words are never re-listened};}
        % after listening, it writes its OWN note: cache +1 entry
        \visible<4->{\node[draw, fill=msyellow!45, minimum width=0.95cm, minimum height=0.5cm] (nnew) at (7.5,-1.15) {K\,V};}
        \visible<4->{\draw[->, thick, msred] (7.95,-0.33) -- (7.95,-0.88);}
        \visible<4->{\node[font=\small, text=msred] at (2.6,-2.75) {one new note per word: the stack grows by exactly one entry};}
    \end{tikzpicture}
    \end{center}
    \visible<5->{\begin{itemize}
        \item A long chat = a tall note stack --- that's why long conversations get slower and heavier
    \end{itemize}}
    % PRESENTER: this is the KV cache without the acronym. Beat to land:
    % we never re-listen to old words, we keep notes. Tall stack = slow and
    % heavy is exactly why long chats cost more and hit context limits.
\end{frame}
=== mlp
% ========================================
% Inside the MLP — zoom into one block. Attention gathered WHO matters;
% the MLP is the think-about-it/recall step: one vector in, a wall of
% neurons where a FEW light up (sparsity), transformed vector out.
% ========================================
\section{Inside the Think Box}

\begin{frame}{One block, zoomed in: the MLP\hfill\includegraphics[height=0.45cm]{images/icons/leisure-video-game.pdf}}
    \begin{center}
    \begin{tikzpicture}[font=\small]
        % the vector arrives carrying the attention verdict
        \visible<1->{\node[draw, rounded corners, fill=msblue!20, minimum width=2.5cm, minimum height=0.85cm] (vin) at (0,0) {gathered meaning};}
        \visible<2->{\draw[->, thick] (vin.east) -- (2.75,0);}
        % the wall of neurons --- all dark at first
        \visible<2->{\foreach \x in {0,...,5} \foreach \y in {0,...,3}
            \fill[msblack!15] (3.45 + 0.45*\x, -0.68 + 0.45*\y) circle (0.13);}
        \visible<2->{\node[font=\scriptsize, text=msblack!60] at (4.46,-1.35) {the MLP: a wall of tiny neurons};}
        % ...a few light up, most stay dark
        \visible<3->{\foreach \p in {(3.90,0.22),(4.80,-0.23),(5.25,0.67),(4.35,-0.68)} {
            \fill[msgreen!30] \p circle (0.24); \fill[msgreen!85] \p circle (0.13); }}
        \visible<3->{\node[font=\small, text=msgreen!70!black] at (4.46,1.35) {only a few fire for this thought};}
        % the transformed vector leaves
        \visible<4->{\draw[->, thick] (5.75,0) -- (6.45,0);}
        \visible<4->{\node[draw, rounded corners, fill=msgreen!20, minimum width=2.5cm, minimum height=0.85cm] (vout) at (8.0,0) {thought it over};}
    \end{tikzpicture}
    \end{center}
    \visible<5->{\begin{itemize}
        \item Attention = \emph{who matters}; the MLP = \emph{what to do about it} --- the model's thinking-with-what-you-know step
    \end{itemize}}
    % PRESENTER: the sparsity is the point — a handful of neurons fire and
    % the wall stays dark; different thoughts light different neurons.
    % FYI for you, not for them: this echoes the ~27k-neuron layers our
    % research SAEs (sparse autoencoders) study in these models.
\end{frame}
