% ========================================
% Step 1 — tokens: text chopped into LEGO bricks.
% Show, don't tell: the sentence stays on screen while it is CUT (scissors),
% the bricks drop out underneath, then each brick turns into the ID number
% the model actually receives, and a long word snaps into three bricks.
% Presenter: the model never sees letters, only tokens. Emoji and names get
% chopped too --- that's why AI is sometimes clumsy with unusual spellings.
% ========================================
\section{Step 1: Chop it up}

\begin{frame}{Tokens --- the LEGO bricks of text\hfill\includegraphics[height=0.45cm]{images/icons/interface-searching.pdf}}
    \begin{itemize}
        \item First, the sentence is chopped into chunks called \textbf{tokens}
    \end{itemize}
    \begin{center}
    \begin{tikzpicture}[font=\normalsize,
            brick/.style={draw, rounded corners=2pt, minimum height=0.8cm, inner sep=2pt}]
        % the sentence stays up the whole time, so before/after sit together
        \node[font=\Large, inner xsep=0pt, anchor=base west] (w0) at (1.05,1.55) {The};
        \foreach \w [count=\i from 1, evaluate=\i as \p using int(\i-1)] in {robot, read, a, book}
            \node[font=\Large, inner xsep=0pt, anchor=base west] (w\i) at ([xshift=0.32cm]w\p.base east) {\w};
        % snip between every word
        \visible<2->{\foreach \i in {0,...,3} {
            \coordinate (cut) at ($(w\i.east)!0.5!(w\the\numexpr\i+1\relax.west)$);
            \draw[msred, thick, dashed] ($(cut)+(0,-0.35)$) -- ($(cut)+(0,0.4)$);
            \node[text=msred, font=\normalsize] at ($(cut)+(0,0.62)$) {\ding{34}};
        }}
        % the bricks drop out underneath, studs and all
        \visible<3->{
            \node[brick, fill=msblue!20,      minimum width=1.5cm] (a) at (0,0)    {The};   \studs{a}{msblue!20}
            \node[brick, fill=msgreen!20,     minimum width=1.9cm] (b) at (2.0,0)  {robot}; \studs{b}{msgreen!20}
            \node[brick, fill=msorange!20,    minimum width=1.8cm] (c) at (4.15,0) {read};  \studs{c}{msorange!20}
            \node[brick, fill=msyellow!25,    minimum width=1.2cm] (d) at (5.95,0) {a};     \studs{d}{msyellow!25}
            \node[brick, fill=msturquoise!20, minimum width=1.8cm] (e) at (7.75,0) {book};  \studs{e}{msturquoise!20}
        }
        % what the model is really handed: one ID number per brick
        \visible<4->{
            \foreach \n/\id in {a/464, b/9379, c/1100, d/257, e/1492}
                \node[font=\ttfamily\bfseries, text=msblue] at ([yshift=-0.45cm]\n.south) {\id};
            \node[font=\small, text=msblue, anchor=east] at (-0.95,-0.85) {what the model sees:};
        }
        % a rarer word is not one brick --- it snaps into pieces
        \visible<5->{
            \node[font=\large, anchor=east] (long) at (2.4,-1.95) {skateboarding};
            \draw[->, thick, msblack!70] (long.east) -- ++(0.55,0);
            \node[brick, fill=msgreen!20,  minimum width=1.5cm, anchor=west] (s1) at (3.2,-1.95) {skate}; \studs{s1}{msgreen!20}
            \node[brick, fill=msorange!20, minimum width=1.5cm, right=0.12cm of s1] (s2) {board};      \studs{s2}{msorange!20}
            \node[brick, fill=mspurple!15, minimum width=1.0cm, right=0.12cm of s2] (s3) {ing};        \studs{s3}{mspurple!15}
            \node[font=\small, text=msblue, anchor=west] at ([xshift=0.25cm]s3.east) {rare word = several bricks};
        }
    \end{tikzpicture}
    \end{center}
    \visible<6->{\begin{itemize}
        \item Chunks are easier to count, stack and reuse --- just like LEGO
    \end{itemize}}
    % PRESENTER: click 1 = the sentence; click 2 = snip snip (scissors);
