        \visible<2->{\node[draw, very thick, rounded corners, fill=msred!30, minimum width=1.4cm, minimum height=0.75cm] at (1.55*6,0) {\textbf{it}};}
        % arcs from "it" (t6). Same bend for every target, so the height
        % grows with distance and the arcs NEST instead of crossing.
        % Click 3: it looks at everyone, all lines equal and thin.
        \only<3>{
            \foreach \j in {0,...,5} \draw[->, msblack!60, line width=0.8pt] (t6.north) to[bend right=38] (t\j.north);
            \foreach \j in {7,8}     \draw[->, msblack!60, line width=0.8pt] (t6.north) to[bend left=38]  (t\j.north);
        }
        % Click 4+: it decides who matters --- thickness = how much.
        \visible<4->{
