            \draw[->, msblack!25, line width=0.6pt] (t6.north) to[bend left=38] (t7.north);
            \draw[->, msblack!55, line width=1.2pt] (t6.north) to[bend right=38] (t1.north);  % dragon: considered
            \draw[->, msorange,   line width=2.0pt] (t6.north) to[bend left=38]  (t8.north);  % shiny: the clue
            \draw[->, msorange,   line width=3.6pt] (t6.north) to[bend right=38] (t4.north);  % gold: the answer
