        \node[font=\small, text=msblack!70, anchor=north west] at (tray.south west) {the note stack (one sticky note per word)};
        % word-5 state: five bricks, each with its sticky note in the tray
        \foreach \w [count=\i from 0] in {The, dragon, kept, the, gold} {
            \node[draw, rounded corners, fill=msblue!12, minimum width=1.3cm, minimum height=0.7cm] (b\i) at (1.6*\i,0) {\w};
